		/*
             SQL ID : ExamMapper.quizDtlSelect
             설  명  : 퀴즈상세조회
         */
         SELECT
         	  EXAM_DTL.*
		  FROM TB_LMS_EXAM_DTL EXAM_DTL
		 WHERE EXAM_BSC_ID = #{examBscId}


		 	   AND EXAM_DTL_ID = #{examDtlId}


			   AND ROWNUM = 1

mapper.insert:
		/*
             SQL ID : ExamMapper.examBscRegist
             설  명  : 시험기본등록
         */
         INSERT INTO TB_LMS_EXAM_BSC (
         	  EXAM_BSC_ID
         	, SBJCT_ID
			, LCTR_WKNO_SCHDL_ID
			, EXAM_GRP_ID
			, EXAM_TYCD
			, EXAM_GBNCD
			, EXAM_TTL
			, EXAM_CTS
			, TKEXAM_MTHD_CD
			, QSTN_DSPLY_GBNCD
			, EXAMPPR_OYN
			, AVG_MRK_OYN
			, MRK_OPEN_SDTTM
			, IMDT_ANSW_SHT_INQYN
			, MAX_TKEXAM_CNT
			, MRK_OYN
			, DVCLAS_REGYN
			, QSTN_RNDMYN
			, QSTN_VWITM_RNDMYN
			, QSTN_CNDDT_USEYN
			, MRK_RFLTYN
			, MRK_RFLTRT
			, EXAMTM_ALLOC_GBNCD
			, EXAMTM_EXPSR_TYCD
			, TEAM_GRP_SUBASMT_STNGYN
			, RGTR_ID
			, REG_DTTM
         ) VALUES (
         	  #{examBscId}
         	, #{sbjctId}
         	, #{lctrWknoSchdlId}
         	, #{examGrpId}
			, #{examTycd}
			, #{examGbncd}
			, #{examTtl}
			, #{examCts}
			, #{tkexamMthdCd}
			, #{qstnDsplyGbncd}
			, #{exampprOyn}
			, #{avgMrkOyn}
			, #{mrkOpenSdttm}
			, #{imdtAnswShtInqyn}
			, #{maxTkexamCnt}
			, #{mrkOyn}
			, #{dvclasRegyn}
			, #{qstnRndmyn}
			, #{qstnVwitmRndmyn}
			, #{qstnCnddtUseyn}
			, #{mrkRfltyn}
			, #{mrkRfltrt}
			, #{examtmAllocGbncd}
			, #{examtmExpsrTycd}
			, #{teamGrpSubasmtStngyn}
			, #{rgtrId}
			, FN_DTTM()
         )

		/*
             SQL ID : ExamMapper.examDtlRegist
             설  명  : 시험상세등록
         */
         INSERT INTO TB_LMS_EXAM_DTL (
         	  EXAM_DTL_ID
			, EXAM_BSC_ID
			, EXAM_TTL
			, EXAM_CTS
			, EXAM_MNTS
			, EXAMTM_LMTYN
			, EXAM_PSBL_SDTTM
			, EXAM_PSBL_EDTTM
			, PASS_SCR
			, CNSDR_ADD_MNTS
			, REEXAMYN
			, REEXAM_PSBL_SDTTM
			, REEXAM_PSBL_EDTTM
			, REEXAM_MRK_RFLTRT
			, RGTR_ID
			, REG_DTTM
         ) VALUES (
         	  #{examDtlId}
			, #{examBscId}
			, #{examTtl}
			, #{examCts}
			, #{examMnts}
			, #{examtmLmtyn}
			, #{examPsblSdttm}
			, #{examPsblEdttm}
			, #{passScr}
			, #{cnsdrAddMnts}
			, #{reexamyn}
			, #{reexamPsblSdttm}
			, #{reexamPsblEdttm}
			, #{reexamMrkRfltrt}
			, #{rgtrId}
			, FN_DTTM()
         )

