             SQL ID : ExamDAO.examEvlSbstDelete
             설  명  : 시험평가대체삭제
        */
        DELETE FROM TB_LMS_EXAM_EVL_SBST
         WHERE EXAM_SBST_ID = #{examSbstId}

mapper.select:
/* SQL ID : ExamDAO.profAuthrtSbjctQuizList 설 명 : 교수권한과목퀴즈목록조회 */ SELECT ROW_NUMBER() OVER(ORDER BY EXAM_BSC.EXAM_BSC_ID DESC) AS LINE_NO , EXAM_BSC.EXAM_BSC_ID , EXAM_BSC.EXAM_TTL , SBJCT.SBJCT_ID , SBJCT.SBJCTNM , SBJCT.DVCLAS_NO , (SELECT CDNM FROM TB_LMS_CMMN_CD WHERE UP_CD = 'EXAM_GBNCD' AND CD = EXAM_BSC.EXAM_GBNCD) AS EXAM_GBNNM , COUNT(1) OVER() AS TOTAL_CNT FROM TB_LMS_SBJCT_ADM SBJCT_ADM JOIN TB_LMS_EXAM_BSC EXAM_BSC ON SBJCT_ADM.SBJCT_ID = EXAM_BSC.SBJCT_ID AND EXAM_BSC.DELYN = 'N' AND EXAM_BSC.USEYN = 'Y' JOIN TB_LMS_SBJCT SBJCT ON SBJCT.SBJCT_ID = EXAM_BSC.SBJCT_ID LEFT JOIN TB_LMS_SMSTR_CHRT SMSTR_CHRT ON (SBJCT.SMSTR_CHRT_ID = SMSTR_CHRT.SMSTR_CHRT_ID AND SBJCT.SBJCT_REF_TYCD = 'CHRT') WHERE SBJCT_ADM.USER_ID = #{userId} AND EXAM_BSC.EXAM_GBNCD IN ('QUIZ', 'QUIZ_TEAM') AND EXAM_BSC.EXAM_TYCD = 'QUIZ' AND SBJCT_ADM.SBJCT_ADM_TYCD = 'PROF'
AND SBJCT.SMSTR_CHRT_ID = #{smstrChrtId}
AND SBJCT.SBJCT_ID = #{sbjctId}
AND LOWER(EXAM_BSC.EXAM_TTL) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
ORDER BY EXAM_BSC.EXAM_BSC_ID

/* SQL ID : ExamDAO.quizTeamGrpSubQuizList 설 명 : 퀴즈팀그룹부퀴즈목록조회 */ SELECT TEAM.TEAM_ID , TEAM.TEAMNM , NVL((SELECT USR.USERNM FROM TB_LMS_USER USR JOIN TB_LMS_TEAM_MBR TEAM_MBR ON USR.USER_ID = TEAM_MBR.USER_ID WHERE TEAM_MBR.LDRYN = 'Y' AND TEAM_MBR.TEAM_ID = TEAM.TEAM_ID), '-') AS leaderNm , (SELECT COUNT(tlts.USER_ID) FROM TB_LMS_TEAM_MBR tlts WHERE tlts.TEAM_ID = TEAM.TEAM_ID) AS teamMbrCnt , EXAM_DTL.EXAM_TTL , EXAM_DTL.EXAM_CTS , EXAM_DTL.EXAM_DTL_ID , FN_REF_FILE_CNT(EXAM_DTL.EXAM_DTL_ID) AS FILE_CNT FROM TB_LMS_TEAM TEAM LEFT JOIN TB_LMS_EXAM_TRGTR EXAM_TRGTR ON TEAM.TEAM_ID = EXAM_TRGTR.TEAM_ID AND EXAM_TRGTR.EXAM_DTL_ID IN (SELECT EXAM_DTL_ID FROM TB_LMS_EXAM_BSC WHERE EXAM_BSC_ID = #{examBscId}) LEFT JOIN TB_LMS_EXAM_DTL EXAM_DTL ON EXAM_TRGTR.EXAM_DTL_ID = EXAM_DTL.EXAM_DTL_ID AND EXAM_DTL.DELYN = 'N' AND EXAM_DTL.USEYN = 'Y' AND EXAM_DTL.EXAM_BSC_ID = #{examBscId} WHERE TEAM.TEAM_GRP_ID = #{teamGrpId}
AND EXAM_DTL.EXAM_BSC_ID = #{examBscId}
ORDER BY TEAM.TEAM_ID ASC

mapper.update:
		/*
             SQL ID : ExamDAO.quizMrkRfltrtListModify
             	설  명 : 퀴즈성적반영비율목록수정
         */

         UPDATE TB_LMS_EXAM_BSC SET
         	  MDFR_ID = #{item.mdfrId}
         	, MOD_DTTM = FN_DTTM()
         	, MRK_RFLTRT = #{item.mrkRfltrt}
          WHERE EXAM_BSC_ID = #{item.examBscId}

		/*
             SQL ID : ExamDAO.quizRetkexamListModify
             	설  명 : 퀴즈재응시목록수정
         */

         UPDATE TB_LMS_EXAM_DTL SET
         	  MDFR_ID = #{item.mdfrId}
         	, MOD_DTTM = FN_DTTM()
         	, REEXAMYN = #{item.reexamyn}
         	, REEXAM_PSBL_SDTTM = #{item.reexamPsblSdttm}
         	, REEXAM_PSBL_EDTTM = #{item.reexamPsblEdttm}
         	, REEXAM_MRK_RFLTRT = #{item.reexamMrkRfltrt}
          WHERE EXAM_DTL_ID = #{item.examDtlId}

mapper.select:
		/*
             SQL ID : ExamDAO.qstnCopySmstrList
             	설  명 : 문제가져오기학기기수목록조회
         */
        SELECT
			  SMSTR_CHRT_ID
			, SMSTR_CHRTNM
		  FROM TB_LMS_SMSTR_CHRT
		 WHERE ORG_ID = #{orgId}

		 	AND DGRS_YR = #{dgrsYr}

/* SQL ID : ExamDAO.smstrChrtSbjctList 설 명 : 학기기수과목목록조회 */ SELECT SBJCT.SBJCT_ID , SBJCT.SBJCTNM , SBJCT.DVCLAS_NO FROM TB_LMS_SBJCT SBJCT JOIN TB_LMS_SMSTR_CHRT SMSTR ON SBJCT.SMSTR_CHRT_ID = SMSTR.SMSTR_CHRT_ID WHERE SBJCT.DELYN = 'N' AND SBJCT.USEYN = 'Y' AND SMSTR.ORG_ID = #{orgId}
AND SMSTR.SMSTR_CHRT_ID = #{smstrChrtId}
AND SBJCT.SBJCT_YR = #{sbjctYr}

mapper.sql:
SELECT ROW_NUMBER() OVER( ORDER BY /* 팀 시험이 아닐 경우 정렬 기준 (이름) */ CASE WHEN A.TEAM_ID IS NULL THEN A.USERNM END ASC /* 팀 시험일 경우 정렬 기준 (팀 - 팀장 - 이름) */ , CASE WHEN A.TEAM_ID IS NOT NULL THEN A.TEAM_ID END ASC , CASE WHEN A.TEAM_ID IS NOT NULL THEN A.LDRYN END DESC , CASE WHEN A.TEAM_ID IS NOT NULL THEN A.USERNM END ASC ) AS LINE_NO /* Row Number */ , A.SBJCT_ID AS "SBJCT_ID" /* 과목 ID */ , A.TEAM_ID AS "TEAM_ID" /* 팀 ID */ , A.TEAMNM AS "TEAMNM" /* 팀명 */ , A.DEPTNM AS "DEPTNM" /* 학과명 */ -- , A.USER_RPRS_ID AS "USER_RPRS_ID" /* 대표 ID */ , A.STDNT_NO AS "STDNT_NO" /* 학번 */ , A.USER_ID AS "USER_ID" /* 사용자 ID */ , A.USERNM AS "USERNM" /* 이름 */ , A.LDRYN AS "LDRYN" /* 리더 여부 */ , A.EXAM_SCR AS "EXAM_SCR" /* 시험 점수 */ , A.TOT_SCR AS "TOT_SCR" /* 평가 점수 */ , A.EXAM_DTL_ID AS "EXAM_DTL_ID" /* 시험 상세 ID */ , A.TKEXAM_CMPTNYN AS "TKEXAM_CMPTNYN" /* 응시상태 */ , A.TKEXAM_CNT AS "TKEXAM_CNT" /* 응시 횟수 */ , A.EVLYN AS "EVLYN" /* 평가여부 */ , A.TKEXAM_SDTTM AS "TKEXAM_SDTTM" /* 응시 시작일 */ , A.TKEXAM_EDTTM AS "TKEXAM_EDTTM" /* 응시 종료일 */ , A.TKEXAM_ID AS "TKEXAM_ID" /* 시험 응시 ID */ , A.MOBILE_NO AS "MOBILE_NO" /* 사용자 전화번호 */ , A.EMAIL AS "EMAIL" /* 사용자 이메일 */ , CASE WHEN A.TKEXAM_SDTTM IS NULL THEN CASE WHEN A.RETKEXAM_YN = 'Y' THEN 'INIT' ELSE 'NOTKEXAM' END WHEN A.TKEXAM_CMPTNYN = 'Y' THEN 'COMPLETED' ELSE 'TKEXAMING' END AS "TKEXAM_CMPTN_GBNCD" /* 응시 여부 */ FROM ( WITH DTL AS ( SELECT EXAM_DTL_ID FROM TB_LMS_EXAM_DTL WHERE DELYN = 'N' AND USEYN = 'Y' AND EXAM_BSC_ID = #{examBscId} ) , TEAM AS ( SELECT EXAM_TRGTR.EXAM_DTL_ID , TEAM.TEAM_ID , TEAM.TEAMNM , TEAM_MBR.USER_ID , TEAM_MBR.LDRYN FROM TB_LMS_TEAM TEAM JOIN TB_LMS_EXAM_TRGTR EXAM_TRGTR ON TEAM.TEAM_ID = EXAM_TRGTR.TEAM_ID JOIN TB_LMS_TEAM_MBR TEAM_MBR ON TEAM.TEAM_ID = TEAM_MBR.TEAM_ID WHERE TEAM.TEAM_CPST_CMPTNYN = 'Y' AND EXAM_TRGTR.EXAM_DTL_ID IN (SELECT EXAM_DTL_ID FROM DTL)) , TKEXAM AS ( SELECT TKEXAM.EXAM_DTL_ID , TKEXAM.TKEXAM_ID , TKEXAM.USER_ID , TKEXAM.TKEXAM_CNT , TKEXAM.TKEXAM_SDTTM , TKEXAM.TKEXAM_EDTTM , TKEXAM.TKEXAM_CMPTNYN , TKEXAM_RSLT.EVLYN , TKEXAM_RSLT.TOT_SCR , TKEXAM.RETKEXAM_YN , QS.EXAM_SCR FROM TB_LMS_TKEXAM TKEXAM LEFT JOIN TB_LMS_TKEXAM_RSLT TKEXAM_RSLT ON TKEXAM.TKEXAM_ID = TKEXAM_RSLT.TKEXAM_ID AND TKEXAM.USER_ID = TKEXAM_RSLT.USER_ID LEFT JOIN ( SELECT ANSW.USER_ID , EXAMPPR.TKEXAM_ID , SUM(ANSW.SCR) AS EXAM_SCR FROM TB_LMS_TKEXAM_ANSW_SHT ANSW JOIN TB_LMS_EXAMPPR EXAMPPR ON ANSW.EXAMPPR_ID = EXAMPPR.EXAMPPR_ID AND ANSW.USER_ID = EXAMPPR.USER_ID GROUP BY ANSW.USER_ID , EXAMPPR.TKEXAM_ID ) QS ON TKEXAM.TKEXAM_ID = QS.TKEXAM_ID AND TKEXAM.USER_ID = QS.USER_ID WHERE TKEXAM.DELYN = 'N' AND TKEXAM.EXAM_DTL_ID IN (SELECT EXAM_DTL_ID FROM DTL)) SELECT ATNDLC.SBJCT_ID , TM.TEAM_ID , TM.TEAMNM , NVL((SELECT DEPTNM FROM TB_LMS_DEPT WHERE DEPT_ID = USR.DEPT_ID),'-') AS DEPTNM , NVL(USR.STDNT_NO,'-') AS STDNT_NO , (SELECT CNTCT FROM TB_LMS_USER_CNTCT WHERE CNTCT_TYCD = 'MBL_PHN' AND USER_ID = ATNDLC.USER_ID) AS MOBILE_NO , (SELECT CNTCT FROM TB_LMS_USER_CNTCT WHERE CNTCT_TYCD = 'INDV_EML' AND USER_ID = ATNDLC.USER_ID) AS EMAIL , ATNDLC.USER_ID -- , USR.USER_RPRS_ID , USR.USERNM , TM.LDRYN , CASE WHEN EXAM_BSC.EXAM_GBNCD IN (SELECT CD FROM TB_LMS_CMMN_CD WHERE UP_CD = 'EXAM_GBNCD' AND CD LIKE '%TEAM%') THEN TM.EXAM_DTL_ID ELSE (SELECT EXAM_DTL_ID FROM DTL) END EXAM_DTL_ID , CASE WHEN EXAM_BSC.EXAM_GBNCD IN (SELECT CD FROM TB_LMS_CMMN_CD WHERE UP_CD = 'EXAM_GBNCD' AND CD LIKE '%TEAM%') THEN TKEXAM_TEAM.TKEXAM_ID ELSE TKEXAM_INDI.TKEXAM_ID END AS TKEXAM_ID , NVL(CASE WHEN EXAM_BSC.EXAM_GBNCD IN (SELECT CD FROM TB_LMS_CMMN_CD WHERE UP_CD = 'EXAM_GBNCD' AND CD LIKE '%TEAM%') THEN TKEXAM_TEAM.EXAM_SCR ELSE TKEXAM_INDI.EXAM_SCR END, 0) AS EXAM_SCR , NVL(CASE WHEN EXAM_BSC.EXAM_GBNCD IN (SELECT CD FROM TB_LMS_CMMN_CD WHERE UP_CD = 'EXAM_GBNCD' AND CD LIKE '%TEAM%') THEN TKEXAM_TEAM.TOT_SCR ELSE TKEXAM_INDI.TOT_SCR END, 0) AS TOT_SCR , CASE WHEN EXAM_BSC.EXAM_GBNCD IN (SELECT CD FROM TB_LMS_CMMN_CD WHERE UP_CD = 'EXAM_GBNCD' AND CD LIKE '%TEAM%') THEN TKEXAM_TEAM.TKEXAM_SDTTM ELSE TKEXAM_INDI.TKEXAM_SDTTM END AS TKEXAM_SDTTM , CASE WHEN EXAM_BSC.EXAM_GBNCD IN (SELECT CD FROM TB_LMS_CMMN_CD WHERE UP_CD = 'EXAM_GBNCD' AND CD LIKE '%TEAM%') THEN TKEXAM_TEAM.TKEXAM_EDTTM ELSE TKEXAM_INDI.TKEXAM_EDTTM END AS TKEXAM_EDTTM , NVL(CASE WHEN EXAM_BSC.EXAM_GBNCD IN (SELECT CD FROM TB_LMS_CMMN_CD WHERE UP_CD = 'EXAM_GBNCD' AND CD LIKE '%TEAM%') THEN TKEXAM_TEAM.TKEXAM_CMPTNYN ELSE TKEXAM_INDI.TKEXAM_CMPTNYN END,'N') AS TKEXAM_CMPTNYN , NVL(CASE WHEN EXAM_BSC.EXAM_GBNCD IN (SELECT CD FROM TB_LMS_CMMN_CD WHERE UP_CD = 'EXAM_GBNCD' AND CD LIKE '%TEAM%') THEN TKEXAM_TEAM.TKEXAM_CNT ELSE TKEXAM_INDI.TKEXAM_CNT END, 0) AS TKEXAM_CNT , NVL(CASE WHEN EXAM_BSC.EXAM_GBNCD IN (SELECT CD FROM TB_LMS_CMMN_CD WHERE UP_CD = 'EXAM_GBNCD' AND CD LIKE '%TEAM%') THEN TKEXAM_TEAM.EVLYN ELSE TKEXAM_INDI.EVLYN END,'N') AS EVLYN , NVL(CASE WHEN EXAM_BSC.EXAM_GBNCD IN (SELECT CD FROM TB_LMS_CMMN_CD WHERE UP_CD = 'EXAM_GBNCD' AND CD LIKE '%TEAM%') THEN TKEXAM_TEAM.RETKEXAM_YN ELSE TKEXAM_INDI.RETKEXAM_YN END,'N') AS RETKEXAM_YN FROM TB_LMS_ATNDLC ATNDLC JOIN TB_LMS_EXAM_BSC EXAM_BSC ON ATNDLC.SBJCT_ID = EXAM_BSC.SBJCT_ID AND EXAM_BSC.USEYN = 'Y' AND EXAM_BSC.DELYN = 'N' JOIN TB_LMS_USER USR ON ATNDLC.USER_ID = USR.USER_ID AND USR.USER_ID_STSCD = 'APRV_CMPTN' AND USR.USER_TYCD = 'STDNT' LEFT JOIN TEAM TM ON TM.USER_ID = ATNDLC.USER_ID LEFT JOIN TKEXAM TKEXAM_TEAM ON TKEXAM_TEAM.EXAM_DTL_ID = TM.EXAM_DTL_ID AND TKEXAM_TEAM.USER_ID = ATNDLC.USER_ID LEFT JOIN TKEXAM TKEXAM_INDI ON TKEXAM_INDI.USER_ID = ATNDLC.USER_ID WHERE ATNDLC.AUDITYN = 'N' AND ATNDLC.ATNDLC_STSCD = 'APPROVE' AND EXAM_BSC.EXAM_BSC_ID = #{examBscId} ) A
AND ( A.TKEXAM_CMPTNYN = #{tkexamCmptnyn} OR A.TKEXAM_SDTTM IS NOT NULL)
AND A.TKEXAM_CMPTNYN = #{tkexamCmptnyn}
AND A.EVLYN = #{evlyn}
AND ( LOWER(A.DEPTNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(A.STDNT_NO) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(A.USERNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) )

