/*
    SQL ID : ExamDAO.registStdntAbsnce
    설명 : 학습자 결시신청 등록
*/
INSERT INTO
    TB_LMS_EXAM_ABSNCE
        ( EXAM_ABSNCE_ID
        , EXAM_BSC_ID
        , USER_ID
        , ABSNCE_TTL
