        , #{absnceTtl}
        , #{absnceCts}
        , #{absnceAplyStscd}
        , #{userId}
        , FN_DTTM()
        , #{absnceRfltrt} )

/*
    SQL ID : ExamDAO.registStdntSprtAply
    설명 : 학습자 장애인/고령자 시험지원 등록
*/
INSERT INTO
    TB_LMS_EXAM_SPRT_APLY
        ( EXAM_SPRT_APLY_ID
        , EXAM_BSC_ID
        , USER_ID
        , APLY_STSCD
        , ADD_MNTS
        , RGTR_ID
        , REG_DTTM
        , SPRT_APLY_CTS
        , EXAM_SPRT_APLY_GRP_ID )
VALUES
        ( #{examSprtAplyId}
        , #{examBscId}
        , #{userId}
        , #{aplyStscd}
        , #{addMnts}
        , #{rgtrId}
        , FN_DTTM()
        , #{sprtAplyCts}
        , #{examSprtAplyGrpId} )

/*
    SQL ID : ExamDAO.modifyStdntSprtCnclAply
    설명 : 학습자 장애인/고령자 시험지원 취소
*/
UPDATE
    TB_LMS_EXAM_SPRT_APLY
SET
    CNCL_APLY_STSCD = #{cnclAplyStscd}
    , MDFR_ID       = #{mdfrId}
    , MOD_DTTM      = FN_DTTM()
WHERE
    EXAM_SPRT_APLY_ID = #{examSprtAplyId}

mapper.sql:
SELECT ROW_NUMBER() OVER(ORDER BY ORG.ORGNM, SMST.DGRS_SMSTR_CHRT, ATND.SBJCT_ID, USR.USERNM) AS "LINE_NO" , ORG.ORGNM , SMST.DGRS_YR , SMST.DGRS_SMSTR_CHRT , DEPT.DEPTNM , SBJCT.CRCLMN_NO , SBJCT.SBJCTNM , SBJCT.DVCLAS_NCKNM , USR.STDNT_NO , USR.USERNM , CASE WHEN USR.DSBLYN = 'Y' THEN '장애인' WHEN USR.SNRYN = 'Y' THEN '고령자' ELSE NULL END AS "GUBUN" , MID_CMMN1.CDNM || '/' || LST_CMMN1.CDNM AS "EXAM_GBNNM" , CMMN1.CDNM AS "EXAM_SPRT_APLY_TYNM" , CASE WHEN MID_SPRT.APLY_STSCD = LST_SPRT.APLY_STSCD AND MID_SPRT.APLY_STSCD = 'APRV' THEN CASE WHEN MID_SPRT.ADD_MNTS IS NULL THEN '부여하지 않음' ELSE '연장(' || MID_SPRT.ADD_MNTS || '분)' END || ' / ' || CASE WHEN LST_SPRT.ADD_MNTS IS NULL THEN '부여하지 않음' ELSE '연장(' || LST_SPRT.ADD_MNTS || '분)' END WHEN MID_SPRT.APLY_STSCD = LST_SPRT.APLY_STSCD AND MID_SPRT.APLY_STSCD = 'RJCT' THEN '반려' ELSE '-' END AS "SPRT_RSLT" , CASE WHEN MID_SPRT.CNCL_APLY_STSCD = LST_SPRT.CNCL_APLY_STSCD AND MID_SPRT.CNCL_APLY_STSCD IN ('CNCL_APLY', 'CNCL_RE_APLY') THEN 'Y' ELSE 'N' END AS "CNCL_APLY_YN" , MID_CMMN2.CDNM AS "CNCL_APLY_STSNM" , ATND.USER_ID , ATND.SBJCT_ID , MID_SPRT.EXAM_SPRT_APLY_GRP_ID FROM TB_LMS_ATNDLC ATND JOIN TB_LMS_USER USR ON ATND.USER_ID = USR.USER_ID AND (USR.DSBLYN = 'Y' OR USR.SNRYN = 'Y') JOIN TB_LMS_DEPT DEPT ON USR.DEPT_ID = DEPT.DEPT_ID JOIN TB_LMS_SBJCT SBJCT ON ATND.SBJCT_ID = SBJCT.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT SMST ON SBJCT.SMSTR_CHRT_ID = SMST.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON SMST.ORG_ID = ORG.ORG_ID JOIN TB_LMS_CMMN_CD CMMN1 ON USR.EXAM_SPRT_APLY_TYCD = CMMN1.CD AND CMMN1.UP_CD = 'EXAM_SPRT_APLY_TYCD' /* 시험 정보 (중간) */ JOIN TB_LMS_EXAM_BSC MID_BSC ON ATND.SBJCT_ID = MID_BSC.SBJCT_ID AND MID_BSC.EXAM_GBNCD LIKE '%MID%' JOIN TB_LMS_EXAM_SPRT_APLY MID_SPRT ON MID_BSC.EXAM_BSC_ID = MID_SPRT.EXAM_BSC_ID AND ATND.USER_ID = MID_SPRT.USER_ID LEFT JOIN TB_LMS_CMMN_CD MID_CMMN1 ON MID_BSC.EXAM_GBNCD = MID_CMMN1.CD AND MID_CMMN1.UP_CD = 'EXAM_GBNCD' LEFT JOIN TB_LMS_CMMN_CD MID_CMMN2 ON MID_SPRT.CNCL_APLY_STSCD = MID_CMMN2.CD AND MID_CMMN2.UP_CD = 'CNCL_APLY_STSCD' /* 시험 정보 (기말) */ JOIN TB_LMS_EXAM_BSC LST_BSC ON ATND.SBJCT_ID = LST_BSC.SBJCT_ID AND LST_BSC.EXAM_GBNCD LIKE '%LST%' JOIN TB_LMS_EXAM_SPRT_APLY LST_SPRT ON LST_BSC.EXAM_BSC_ID = LST_SPRT.EXAM_BSC_ID AND ATND.USER_ID = LST_SPRT.USER_ID LEFT JOIN TB_LMS_CMMN_CD LST_CMMN1 ON LST_BSC.EXAM_GBNCD = LST_CMMN1.CD AND LST_CMMN1.UP_CD = 'EXAM_GBNCD' WHERE 1=1
/* 기관 */ AND ORG.ORG_ID = #{orgId}
/* 년도 */ AND SMST.DGRS_YR = #{dgrsYr}
/* 학기기수 */ AND SMST.DGRS_SMSTR_CHRT = #{dgrsSmstrChrt}
/* 학과 */ AND USR.DEPT_ID = #{deptId}
/* 과목 */ AND SBJCT.SBJCT_ID = #{sbjctId}
/* 처리상태 (대기) */ AND MID_SPRT.APLY_STSCD IN ('APLY', 'RE_APLY') AND LST_SPRT.APLY_STSCD IN ('APLY', 'RE_APLY')
/* 처리상태 (완료) */ AND MID_SPRT.APLY_STSCD IN ('APRV', 'RJCT') AND LST_SPRT.APLY_STSCD IN ('APRV', 'RJCT')
/* 검색어 (학번 or 이름) */ AND (LOWER(USR.STDNT_NO) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(USR.USERNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})))

mapper.update:
/*
    SQL ID : ExamDAO.updateSprtAplyStat
    설명 : 관리자 장애인/고령자 시험지원 신청 승인/반려
*/
UPDATE
    TB_LMS_EXAM_SPRT_APLY
SET
    APLY_STSCD      = #{aplyStscd}
    , AUTZR_ID      = #{autzrId}
    , APRVDTTM      = FN_DTTM()
    , ADD_MNTS      = #{addMnts}
    , MDFR_ID       = #{mdfrId}
    , MOD_DTTM      = FN_DTTM()
    , SPRT_APRV_CTS = #{sprtAprvCts}
WHERE
    EXAM_SPRT_APLY_ID = #{examSprtAplyId}

/*
    SQL ID : ExamDAO.updateSprtAplyCnclStat
    설명 : 관리자 장애인/고령자 시험지원 취소신청 승인/반려
*/
UPDATE
    TB_LMS_EXAM_SPRT_APLY
SET
    CNCL_APLY_STSCD = #{cnclAplyStscd}
    , MDFR_ID       = #{mdfrId}
    , MOD_DTTM      = FN_DTTM()
WHERE
    EXAM_SPRT_APLY_GRP_ID = #{examSprtAplyGrpId}
